# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import format_contacts

def _student(last, section="A1", email="x@example.org"):
    return Student("id", last, "Pat", section, email)

class ContactTests(unittest.TestCase):
    def test_rows_sorted_and_aligned(self):
        rows = format_contacts([_student("Zed"), _student("Abe", "B22", "a@e.org")])
        self.assertEqual(rows[0], "Abe, Pat  B22  a@e.org")
        self.assertEqual(rows[1], "Zed, Pat  A1   x@example.org")

    def test_missing_email_names_student(self):
        with self.assertRaisesRegex(ProjectError, "Abe, Pat"):
            format_contacts([_student("Abe", email=None)])

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            format_contacts([])
